import * as THREE from 'three';

/**
 * World scale (documented contract):
 *
 *   HEIGHT_SCALE = 1.0
 *
 * One unit of normalized spectrum value ([0, 1]) maps to exactly one world
 * unit of bar height. A bar whose smoothed value is v is rendered as a box
 * scaled to (v * HEIGHT_SCALE) in Y, repositioned so its base sits at y = 0
 * and it grows upward. Bar widths/spacing are fixed at WIDTH / SPACING world
 * units; bars are laid out in a row along +X starting at x = 0.
 */
export const HEIGHT_SCALE = 1.0;
export const BAR_WIDTH = 0.8;
export const BAR_DEPTH = 0.8;
export const BAR_SPACING = 1.0;

/** Decay rate: values fall toward lower targets at 3 units/sec. */
export const DECAY_PER_SEC = 3;

/**
 * Build a visualizer scene containing n bar meshes in a row.
 * Each mesh is a unit box; per-frame we set scale.y = height and
 * position.y = height / 2 so the box's min.y stays anchored at y = 0.
 *
 * Returns { group, meshes, values } where:
 *   - group:   THREE.Group holding the bars (add to your scene)
 *   - meshes:  array of n THREE.Mesh (BoxGeometry, one per bar)
 *   - values:  Float64Array of n current smoothed heights (world units)
 */
export function buildBars(n) {
  const group = new THREE.Group();
  const geometry = new THREE.BoxGeometry(BAR_WIDTH, 1, BAR_DEPTH);
  const material = new THREE.MeshBasicMaterial({ color: 0x33ff88 });

  const meshes = [];
  const values = new Float64Array(n);

  for (let i = 0; i < n; i++) {
    const mesh = new THREE.Mesh(geometry, material);
    // Start fully collapsed but still anchored at the floor.
    mesh.scale.y = 0;
    mesh.position.set(i * BAR_SPACING, 0, 0);
    group.add(mesh);
    meshes.push(mesh);
  }

  return { group, meshes, values };
}

/**
 * Feed one frame of spectrum data into the visualizer.
 *
 * Per-bar smoothing (attack/decay):
 *   - Attack: if target is higher than the current value, snap instantly.
 *   - Decay:  if target is lower, fall toward it at DECAY_PER_SEC units/sec:
 *         value = max(target, value - DECAY_PER_SEC * dt)
 *
 * Also updates each mesh's transform so heights map through HEIGHT_SCALE
 * and every bar's Box3 min.y remains exactly 0.
 */
export function feedFrame(viz, frame, dt) {
  const { meshes, values } = viz;
  const decayStep = DECAY_PER_SEC * dt;

  for (let i = 0; i < meshes.length; i++) {
    const target = frame[i] ?? 0;
    const next = Math.max(target, values[i] - decayStep);
    values[i] = next;

    const height = next * HEIGHT_SCALE;
    meshes[i].scale.y = height;
    meshes[i].position.y = height / 2; // keep base at y = 0, grow upward
  }
}

/**
 * Snapshot of current smoothed bar heights in world units
 * (identical to viz.values; returned as a plain array for convenience).
 */
export function barHeights(viz) {
  return Array.from(viz.values);
}

